            _scanDebouncer = new Debouncer(ScanPending, TimeSpan.FromSeconds(DEBOUNCE_TIMEOUT_SECONDS), true);
        }
        public void Dispose()
        {
            foreach (var watcher in _fileSystemWatchers.Values)
            {
