                {
                    throw new ArgumentNullException("path");
                }
                _changedPaths.TryAdd(path, rootFolder);
                _scanDebouncer.Execute();
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Exception in ReportFileSystemChanged. Path: {0}", e.FullPath);
            }
        }
