def next_identifier(prefix=''):
	global unique_identifier
	unique_identifier += 1
	return "%s%d" % (prefix, unique_identifier)
def encode_identifier(value):
	return "".join([(c.isalpha() or c.isdigit()) and c or "_%02x" % ord(c) \
	                       for c in value.encode('utf-8')])
