            @Override
            public void componentShown(ComponentEvent e){
                m_jInspectorDialog.pack();
                m_jInspectorDialog.invalidate();
            }
        }
        private class InspectorWindowAdapter extends WindowAdapter{
            @Override
            public void windowClosed(WindowEvent e){
                removeTabPanes();
