				formatter = value;
			}
		}
		public bool IsInitiating {
			get { return is_initiating; }
			set {
				ThrowIfOpened ();
				is_initiating = value;
			}
		}
		public bool IsOneWay {
			get { return is_oneway; }
			set {
				ThrowIfOpened ();
				is_oneway = value;
			}
		}
		public bool IsTerminating {
			get { return is_terminating; }
