    {
        PhotonEditor win = GetWindow(WindowType, false, CurrentLang.WindowTitle, true) as PhotonEditor;
        win.InitPhotonSetupWindow();
        win.isSetupWizard = false;
        win.SwitchMenuState(GUIState.Main);
