				TlvTypeCodes.ControlParameters_LocalControlFeature, endOffset));
			controlParameters.setOrigin((int)decoder.
			  readOptionalNonNegativeIntegerTlv(TlvTypeCodes.ControlParameters_Origin,
				endOffset));
			controlParameters.setCost((int)decoder.readOptionalNonNegativeIntegerTlv(
			  TlvTypeCodes.ControlParameters_Cost, endOffset));
			// set forwarding flags
			ForwardingFlags flags = new ForwardingFlags();
			flags.setNfdForwardingFlags((int)decoder.
			  readOptionalNonNegativeIntegerTlv(TlvTypeCodes.ControlParameters_Flags,
				endOffset));
			controlParameters.setForwardingFlags(flags);
			// Decode strategy
			if (decoder.peekType(TlvTypeCodes.ControlParameters_Strategy, endOffset)) {
				int strategyEndOffset = decoder.readNestedTlvsStart(TlvTypeCodes.ControlParameters_Strategy);
				decodeName(controlParameters.getStrategy(), new int[1], new int[1], decoder);
				decoder.finishNestedTlvs(strategyEndOffset);
			}
			// Decode expiration period
			controlParameters.setExpirationPeriod((int)decoder.readOptionalNonNegativeIntegerTlv(TlvTypeCodes.ControlParameters_ExpirationPeriod, endOffset));
			decoder.finishNestedTlvs(endOffset);
		}
