		encodeSignatureValue(AbstractSignature signature)
		{
			TlvEncoder encoder = new TlvEncoder(256);
			encoder.writeBlobTlv(TlvTypeCodes.SignatureValue, signature.getSignature().buf());
			return new Blob(encoder.getOutput(), false);
		}
