        private void GlueFreeBlocks()
        {
            RarMemBlock s0 = _tempRarMemBlock1;
            s0.Address = _tempMemBlockPos;
            RarMemBlock p = _tempRarMemBlock2;
            RarMemBlock p1 = _tempRarMemBlock3;
