    private static int peptideLengthIndex(int peptideLength)
    {
        if(peptideLength < MIN_PEPTIDE_LENGTH || peptideLength > REF_PEPTIDE_LENGTH)
            return INVALID_PEP_LEN;
        return peptideLength - MIN_PEPTIDE_LENGTH;
