            this.mixerHandleType = mixerHandleType;
            mixerLine = new MixerInterop.MIXERLINE();
            mixerLine.cbStruct = Marshal.SizeOf(mixerLine);
            mixerLine.dwDestination = destinationIndex;
            mixerLine.dwSource = sourceIndex;
