        new_path = self.rest(1)
        cf = self.fm.thisfile
        if not new_path:
            return self.fm.notify('Syntax: relink <newpath>', bad=True)
        if not cf.is_link:
            return self.fm.notify('%s is not a symlink!' % cf.basename, bad=True)
        if new_path == os.readlink(cf.path):
