     */
    public static final void updateGroup(Player player, GroupEvent groupEvent) {
        PlayerGroup group = player.getPlayerGroup2();
        if (group != null) {
            group.onEvent(new PlayerGroupUpdateEvent(group, player, groupEvent));
        }
