        for (int y = 0; y < ySize; y++)
        {
            for (int x = 0; x < xSize; x++)
            {
                float v = valueAt(x, y);
                Debug.Assert(v >= 0 && v < 256);
                Graphics.CopyTexture(colorMapTexture,
                    0, 0,
