                var unitpos03 = !double.IsNaN(time) ? a.Extend(b, (float) time*speed) : new Vector2();
                var castpos03 = unitpos03.IsValid()
                    ? spell.From.To2D().Extend(unitpos03, spell.From.To2D().Distance(unitpos03) - rad)
