                if (castpos01.IsValid() && castpos02.IsValid() && castpos03.IsValid())
                {
                    var length01 = castpos01.Distance(castpos02);
                    var length02 = castpos02.Distance(castpos03);
                    var Acosb =
                        Math.Acos(
                            Math.Abs(float.IsNaN(math.CosB(spell.From.To2D(), a, b))
                                ? 0.99f
