                        {
                            UnitPosition = unitpos02.To3D(),
                            CastPosition = castpos02.To3D(),
                            Hitchance = HitChance.OutOfRange
                        };
                    }
                }
            }
            return new PredictionOutput
            {
                UnitPosition = unitpos.To3D(),
                CastPosition = castpos.To3D(),
                Hitchance = hitchance
