                Point ret;
                if (this is Shape)
                    ret = (this as Shape).Size * RotationOrigin;
                else if (this is Surface)
                {
                    Size2D s = (this as Surface).Size * RotationOrigin;
                    ret = new Point(s.X, 0, s.Y);
                }
                else ret = new Point(0, 0, 0);
                ret = Matrix.Transform(ret, Matrix.Rotate(Rotation));
                return ret;
            }
        }
