				}
				return false;
			}
			if (user.AccessLevel < Access)
			{
				if (message)
				{
					InternalMessage(user, "You do not have sufficient access to speak in the channel '{0}'", Name);
				}
				return false;
			}
			if (IsUser(user) && user.AccessLevel < AccessLevel.Counselor && Users[user] > DateTime.Now)
			{
