            return self.__class__.__bases__[-1].GetMinimum(self)
        clone = self.Clone()
        for i in xrange(clone.GetNbinsX()):
            clone.SetBinContent(
                i + 1, clone.GetBinContent(i + 1) - clone.GetBinError(i + 1))
        return clone.minimum()
