	 */
	@Override
	public void removeAutonomousListener(String code, String tid,
	    ReportListener listener) {
		if (engine != null) {
			engine.deregister(code, tid, listener);
		}
	}
	/**
	 * This listener will be notified of all autonomous events that originate from
